//! Media player tests with media generated by the bundled FFmpeg CLI.
#![allow(clippy::unwrap_used, clippy::expect_used)]

use estream_media::player::{PixelLayout, PlayState, Player, PlayerSettings};
use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::{Arc, OnceLock};
use std::time::{Duration, Instant};

fn ffmpeg_cli() -> Option<PathBuf> {
    let exe = PathBuf::from(option_env!("FFMPEG_DIR")?)
        .join("bin")
        .join(if cfg!(windows) {
            "ffmpeg.exe"
        } else {
            "ffmpeg"
        });
    exe.exists().then_some(exe)
}

struct Media {
    video: PathBuf,
    short: PathBuf,
    image: PathBuf,
    alpha: PathBuf,
}

fn generate(exe: &Path, args: &[&str], out: &Path) {
    let status = Command::new(exe)
        .args(["-hide_banner", "-loglevel", "error", "-y"])
        .args(args)
        .arg(out)
        .status()
        .unwrap();
    assert!(status.success(), "ffmpeg failed for {}", out.display());
}

/// Test media, generated once per test run.
fn media() -> Option<&'static Media> {
    static MEDIA: OnceLock<Option<Media>> = OnceLock::new();
    MEDIA
        .get_or_init(|| {
            let exe = ffmpeg_cli()?;
            let dir = std::env::temp_dir().join(format!("estream-player-{}", std::process::id()));
            std::fs::create_dir_all(&dir).unwrap();
            let m = Media {
                video: dir.join("bars.mp4"),
                short: dir.join("short.mp4"),
                image: dir.join("blue.png"),
                alpha: dir.join("alpha.mov"),
            };
            generate(
                &exe,
                &[
                    "-f",
                    "lavfi",
                    "-i",
                    "testsrc=size=320x240:rate=30:duration=2",
                    "-f",
                    "lavfi",
                    "-i",
                    "sine=frequency=440:duration=2",
                    "-c:v",
                    "libopenh264",
                    "-c:a",
                    "aac",
                    "-shortest",
                ],
                &m.video,
            );
            generate(
                &exe,
                &[
                    "-f",
                    "lavfi",
                    "-i",
                    "testsrc=size=160x120:rate=30:duration=0.5",
                    "-c:v",
                    "libopenh264",
                ],
                &m.short,
            );
            generate(
                &exe,
                &[
                    "-f",
                    "lavfi",
                    "-i",
                    "color=c=blue:s=32x32",
                    "-frames:v",
                    "1",
                ],
                &m.image,
            );
            generate(
                &exe,
                &[
                    "-f",
                    "lavfi",
                    "-i",
                    "color=c=red@0.5:s=64x64:d=1,format=argb",
                    "-c:v",
                    "qtrle",
                    "-pix_fmt",
                    "argb",
                ],
                &m.alpha,
            );
            Some(m)
        })
        .as_ref()
}

fn settings(items: &[&Path]) -> PlayerSettings {
    PlayerSettings {
        items: items.iter().map(|p| p.to_path_buf()).collect(),
        ..Default::default()
    }
}

fn wait_for(timeout: Duration, mut cond: impl FnMut() -> bool) -> bool {
    let until = Instant::now() + timeout;
    while Instant::now() < until {
        if cond() {
            return true;
        }
        std::thread::sleep(Duration::from_millis(10));
    }
    false
}

fn picture_size(p: &Player) -> Option<(u32, u32, PixelLayout)> {
    let guard = p.try_picture()?;
    guard
        .as_ref()
        .map(|pic| (pic.width, pic.height, pic.layout))
}

#[test]
fn plays_video_and_audio_in_real_time() {
    let Some(m) = media() else { return };
    let player = Player::new(settings(&[&m.video]));
    // Read audio like the mixer does: 480 frames every 10 ms.
    let (mut l, mut r) = (vec![0.0f32; 480], vec![0.0f32; 480]);
    let mut frames = 0usize;
    let mut loud = 0usize;
    let started = Instant::now();
    while started.elapsed() < Duration::from_millis(1200) {
        std::thread::sleep(Duration::from_millis(10));
        let n = player.read_audio(&mut l, &mut r);
        frames += n;
        loud += l[..n].iter().filter(|s| s.abs() > 0.05).count();
    }
    let seq = player.sequence();
    let status = player.status();
    eprintln!("sequence {seq}, audio frames {frames}, status {status:?}");
    assert!(seq > 20, "video advances: {seq}");
    assert_eq!(
        picture_size(&player).map(|p| (p.0, p.1, p.2)),
        Some((320, 240, PixelLayout::Nv12))
    );
    // ~1.1 s of audio expected (minus the lead); allow generous slack.
    assert!(frames > 30_000 && frames < 70_000, "audio frames {frames}");
    assert!(loud > 1000, "the tone is audible");
    assert_eq!(status.state, PlayState::Playing);
    assert_eq!(status.item, "bars.mp4");
    let d = status.duration.unwrap().as_secs_f64();
    assert!((d - 2.0).abs() < 0.2, "duration {d}");
}

#[test]
fn playlist_shows_image_then_video() {
    let Some(m) = media() else { return };
    let player = Player::new(PlayerSettings {
        image_seconds: 0.5,
        ..settings(&[&m.image, &m.short])
    });
    assert!(wait_for(Duration::from_secs(2), || picture_size(&player)
        .is_some_and(|p| p.0 == 32)));
    assert!(
        wait_for(Duration::from_secs(3), || picture_size(&player)
            .is_some_and(|p| p.0 == 160)),
        "then the video: {:?}",
        player.status()
    );
    assert_eq!(player.status().index, 1);
}

#[test]
fn stops_at_the_end_unless_looping() {
    let Some(m) = media() else { return };
    let once = Player::new(PlayerSettings {
        looping: false,
        ..settings(&[&m.short])
    });
    assert!(wait_for(Duration::from_secs(4), || once.status().state
        == PlayState::Ended));
    assert!(picture_size(&once).is_some(), "last frame stays");

    let looping = Player::new(settings(&[&m.short]));
    std::thread::sleep(Duration::from_millis(1600));
    let before = looping.sequence();
    std::thread::sleep(Duration::from_millis(300));
    assert!(
        looping.sequence() > before,
        "still playing after the first pass"
    );
    assert_eq!(looping.status().state, PlayState::Playing);
}

#[test]
fn pause_freezes_position_and_audio() {
    let Some(m) = media() else { return };
    let player = Player::new(settings(&[&m.video]));
    assert!(wait_for(Duration::from_secs(2), || player
        .status()
        .position
        > Duration::from_millis(300)));
    player.set_paused(true);
    assert!(wait_for(Duration::from_secs(1), || player.status().state
        == PlayState::Paused));
    let (pos, seq) = (player.status().position, player.sequence());
    std::thread::sleep(Duration::from_millis(400));
    assert_eq!(player.status().position, pos);
    assert_eq!(player.sequence(), seq);
    let (mut l, mut r) = (vec![0.0f32; 480], vec![0.0f32; 480]);
    assert_eq!(player.read_audio(&mut l, &mut r), 0, "silent while paused");
    player.set_paused(false);
    assert!(wait_for(Duration::from_secs(1), || player.sequence() > seq));
}

#[test]
fn missing_files_are_reported_and_skipped() {
    let Some(m) = media() else { return };
    let missing = m.image.with_file_name("missing.mp4");
    let player = Player::new(settings(&[&missing, &m.image]));
    assert!(wait_for(Duration::from_secs(2), || picture_size(&player).is_some()));
    let error = player.status().error.unwrap();
    assert!(error.contains("missing.mp4"), "{error}");
}

#[test]
fn alpha_video_keeps_transparency() {
    let Some(m) = media() else { return };
    let player = Player::new(settings(&[&m.alpha]));
    assert!(wait_for(Duration::from_secs(2), || picture_size(&player).is_some()));
    let guard = player.try_picture().unwrap();
    let pic = guard.as_ref().unwrap();
    assert_eq!(pic.layout, PixelLayout::Rgba);
    let alpha = pic.data[3];
    assert!((100..=160).contains(&alpha), "half transparent: {alpha}");
}

#[test]
fn players_are_shared_by_source_id() {
    let Some(m) = media() else { return };
    let a = estream_media::player::acquire("src-1", settings(&[&m.video]));
    let b = estream_media::player::acquire("src-1", settings(&[&m.video]));
    assert!(Arc::ptr_eq(&a, &b));
    assert!(estream_media::player::get("src-1").is_some());
    drop((a, b));
    assert!(
        estream_media::player::get("src-1").is_none(),
        "freed with its sources"
    );
}
